-- Rollback: DELETE FROM remediation_contracts WHERE class = 'fm-owner-task-100576-acted-without-approve'; DELETE FROM failure_modes WHERE fm_key = 'owner-task-100576-acted-without-approve'; DELETE FROM control_registry WHERE control IN ('dash-owner-decision-asks-gate', 'owner-prompt-twin-link-handoff-exempt', 'owner-authorization-hold-100576') AND issue_id IN (100360, 100576); UPDATE control_registry SET location = replace(location, 'FAILING CLOSED when the table cannot be read or holds no rows: every card that asks for a decision then offers Diagnose and Done only (1.70.1; the embedded list stays as an extra layer)', 'with an embedded list when the table cannot be read'), evidence = replace(evidence, 'with the table dropped or empty every decision card is owner-only (T18h, and T29 for each of the 73 live patterns)', 'the embedded list stands in without the table') WHERE control = 'dash-owner-decision-hard-marker-gate'; UPDATE remediation_contracts SET verify_probe = 'SELECT ''reask-100140-decided'' AS expected, CASE WHEN EXISTS (SELECT 1 FROM human_responses WHERE key = ''ha:uia-source-fidelity-100140'' AND kind = ''approve'' AND credential = ''owner-session'') AND EXISTS (SELECT 1 FROM owner_prompts WHERE mode = ''task'' AND visitor = ''owner-decision'' AND prompt LIKE ''OWNER-DECISION from %'' AND instr(prompt, ''owner card ha:uia-source-fidelity-100140'') > 0) THEN ''reask-100140-decided'' WHEN EXISTS (SELECT 1 FROM human_responses WHERE key = ''ha:uia-source-fidelity-100140'' AND kind = ''decline'' AND credential = ''owner-session'') AND NOT EXISTS (SELECT 1 FROM human_responses WHERE key = ''ha:uia-source-fidelity-100140'' AND kind = ''approve'') AND NOT EXISTS (SELECT 1 FROM human_actions WHERE slug = ''uia-source-fidelity-100140'' AND status = ''open'') THEN ''reask-100140-decided'' ELSE ''reask-100140-no-decision-reached-the-fleet'' END AS observed', action = replace(action, 'together with the OWNER-DECISION hand-off task (owner_prompts.visitor = owner-decision) once the card is closed because all seven items are decided, or', 'together with the OWNER-DECISION hand-off task (owner_prompts.visitor = owner-decision), or') WHERE class = 'issue-' || (SELECT id FROM agent_issues WHERE title = 'DASH-OWNER-ACTIONS-1: re-ask the owner for the seven decisions of agent_issues 100140 (owner card ha:uia-source-fidelity-100140 was closed with Done because Approve did not exist)' ORDER BY id DESC LIMIT 1) AND instr(verify_probe, '> 0) AND NOT EXISTS (SELECT 1 FROM human_actions WHERE slug = ''uia-source-fidelity-100140'' AND status = ''open'') THEN ''reask-100140-decided'' WHEN EXISTS') > 0; UPDATE agent_issues SET description = replace(replace(description, 'Correction 2026-10-26 (migrations/2026-10-26-dash-owner-actions-followup.sql): no loop reads that row today. No worker.js on main reads human_responses kind approve or the OWNER-DECISION hand-off (only qnfo-fleet-dashboard writes them), so nothing waits for the approve before it works 100576, and the model''s wording ''now owner-authorized'' in that task is not an authorization. Issue 100576 is held by control_registry owner-authorization-hold-100576 and a note on the issue: it must not be executed before the approve exists in human_responses with the OWNER-DECISION hand-off.', 'The loop that works 100576 reads that row and does not treat the task text as the approval.'), '(the server''s own marker) and the card closed because all seven items are decided, or an owner-session decline of every part with the card closed. It does not pass while the card is open (a partial approval proves nothing until the last item is decided),', '(the server''s own marker), or an owner-session decline of every part with the card closed. It does not pass while the card is merely open,') WHERE title = 'DASH-OWNER-ACTIONS-1: re-ask the owner for the seven decisions of agent_issues 100140 (owner card ha:uia-source-fidelity-100140 was closed with Done because Approve did not exist)'; UPDATE agent_issues SET description = substr(description, 1, instr(description, char(10) || char(10) || 'OWNER-AUTHORIZATION-HOLD-1') - 1) WHERE id = 100576 AND instr(description, char(10) || char(10) || 'OWNER-AUTHORIZATION-HOLD-1') > 0; UPDATE belief_registry SET evidence = substr(evidence, 1, instr(evidence, ' Follow-up 2026-10-26 (') - 1) WHERE belief_key = 'dash-owner-done-not-a-decision' AND instr(evidence, ' Follow-up 2026-10-26 (') > 0;
--
-- DASH-OWNER-ACTIONS-1 follow-up (2026-10-26, agent_issues 100360 / 1000412 / 100576, charter pillar: autonomy). Two adversarial reviewers of the merged head
-- (qnfo-fleet-dashboard 1.70.0 and migrations/2026-10-26-dash-owner-actions.sql, both live) found the defects below; qnfo-fleet-dashboard 1.70.1 fixes the two in the
-- dashboard (receipt cards; the hard-marker gate failing open) and this file fixes the rest in qnfo-audit. The already-applied migration is not edited.
--  * agent_issues 1000412 (written by the applied migration) said 'The loop that works 100576 reads that row and does not treat the task text as the approval'. That is
--    false: no worker.js on main reads human_responses kind approve or the OWNER-DECISION hand-off (only qnfo-fleet-dashboard writes them), and agent_issues 100576
--    (open, high, no doer) still says 'now owner-authorized. Apply items 2, 4 and 5' for the owner's own papers. The sentence is replaced by what is true; 100576 gets a
--    note (guarded, appended once) that it is NOT an owner authorization and must not be executed before the approve exists; control_registry records the hold with its
--    reason, release condition and a 120 minute expiry; a detector reads above 0 if 100576 is closed or a new version of an item 2, 4 or 5 paper is recorded with no approve;
--    belief_registry gets the evidence (INSERT OR REPLACE of the one row, created_at kept); decision_log records the decision.
--  * the re-ask probe of agent_issues 1000412 passed once ANY approve row and ANY hand-off task for the card existed, while the card stays open until all seven items
--    are decided: its approve branch now also needs the card closed (guarded; the old probe text is in the Rollback line).
--  * control_registry gets the asks-a-decision gate (decAsksDecision) and the twin-link hand-off exemption (noTwin) the first file did not register, and the hard-marker gate
--    row stops saying an embedded list stands in when the markers cannot be read (it now fails closed).
-- No DELETE or DROP runs here (the DELETE statements belong to the Rollback line, which removes only rows this file inserts), so no BACKUP is taken.

-- Failure mode and detector: a decision-less execution of the held task.
INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius)
VALUES ('owner-task-100576-acted-without-approve',
  'agent_issues 100576 (the dashboard model''s task ''now owner-authorized: execute the seven fixes of agent_issues 100140'') is closed, or a new version of one of the Ignorance Audit papers is recorded, while the owner has recorded no approve for owner card ha:uia-source-fidelity-100140',
  'a model-proposed button (owner_prompts op-mvln7t9l2192) worded the owner''s note-taking as an authorization and filed it as a task for the fleet; no loop reads human_responses kind approve or the OWNER-DECISION hand-off, so nothing separates the model''s wording from the owner''s decision except the issue text, which said it was authorized',
  'DASH-OWNER-ACTIONS-1 follow-up: the issue carries the OWNER-AUTHORIZATION-HOLD-1 note, control_registry owner-authorization-hold-100576 records the reason, the release condition (the approve with its hand-off) and a 120 minute expiry, and this detector counts a violation; on a reading above 0 reopen agent_issues 100576, read paper_revision_log and errata_actions for the paper that changed, restore its previous version through the revision path and ask the owner on the card',
  'remediation_contracts fm-owner-task-100576-acted-without-approve (d1-query: agent_issues 100576 closed, plus paper_revision_log and errata_actions rows created since 2026-10-26 that change a version of ai4metascience-ignorance-audit, ignorance-ai-pipeline-synthesis or universal-ignorance-audit, each counted only while no owner-session approve of ha:uia-source-fidelity-100140 exists; migrations/dash-owner-actions-followup.test.mjs)',
  'fm-owner-task-100576-acted-without-approve',
  '2026-10-26',
  100576,
  NULL,
  'review of the merged DASH-OWNER-ACTIONS-1 head 2026-10-26: agent_issues 100576 open, high, no doer, still says ''now owner-authorized''; agent_issues 1000412 said the loop that works it reads the approve row, which no worker.js on main does',
  'the owner''s own papers are edited, and the task closed as done, on a model''s wording of an authorization the owner has not given (the seven fixes edit authorship wording in papers the owner authored); the three Ignorance Audit papers of agent_issues 100140 and the owner''s trust in the owner queue; no other task is held');

INSERT OR IGNORE INTO remediation_contracts (class, issue_id, precondition, action, verify_probe, verify_transport, max_attempts, escalate_to, expected_cadence_h, status, module, next_due_at)
VALUES ('fm-owner-task-100576-acted-without-approve', NULL,
  'migrations/2026-10-26-dash-owner-actions-followup.sql has an ok row in migration_runs and agent_issues 100576 carries the OWNER-AUTHORIZATION-HOLD-1 note',
  'a reading above 0 means agent_issues 100576 was closed, or a new version of ai4metascience-ignorance-audit, ignorance-ai-pipeline-synthesis or universal-ignorance-audit was recorded, with no owner-session approve of ha:uia-source-fidelity-100140 in human_responses: reopen 100576 if it was closed, read the paper_revision_log or errata_actions row that changed a version, restore the previous version through the revision and errata path of qnfo-research-exec, and ask the owner on the card. The reading returns to 0 by itself once the owner''s approve exists.',
  'SELECT ''0'' AS expected, CAST((SELECT COUNT(*) FROM agent_issues WHERE id = 100576 AND status IN (''closed'', ''resolved'', ''wontfix'') AND NOT EXISTS (SELECT 1 FROM human_responses WHERE key = ''ha:uia-source-fidelity-100140'' AND kind = ''approve'' AND credential = ''owner-session'')) + (SELECT COUNT(*) FROM paper_revision_log WHERE slug IN (''ai4metascience-ignorance-audit'', ''ignorance-ai-pipeline-synthesis'', ''universal-ignorance-audit'') AND created_at >= ''2026-10-26'' AND COALESCE(version_to, '''') <> '''' AND COALESCE(version_to, '''') <> COALESCE(version_from, '''') AND NOT EXISTS (SELECT 1 FROM human_responses WHERE key = ''ha:uia-source-fidelity-100140'' AND kind = ''approve'' AND credential = ''owner-session'')) + (SELECT COUNT(*) FROM errata_actions WHERE slug IN (''ai4metascience-ignorance-audit'', ''ignorance-ai-pipeline-synthesis'', ''universal-ignorance-audit'') AND created_at >= ''2026-10-26'' AND COALESCE(version_to, '''') <> '''' AND COALESCE(version_to, '''') <> COALESCE(version_from, '''') AND NOT EXISTS (SELECT 1 FROM human_responses WHERE key = ''ha:uia-source-fidelity-100140'' AND kind = ''approve'' AND credential = ''owner-session'')) AS TEXT) AS observed',
  'd1-query', 3, 'qnfo-fleet-control', 1, 'active', 'failure-mode', datetime('now', '+60 minutes'));

-- agent_issues 1000412: replace the false sentence and say the approve branch needs the closed card (guarded on the false sentence, so a replay changes nothing).
UPDATE agent_issues SET description = replace(replace(description, 'The loop that works 100576 reads that row and does not treat the task text as the approval.', 'Correction 2026-10-26 (migrations/2026-10-26-dash-owner-actions-followup.sql): no loop reads that row today. No worker.js on main reads human_responses kind approve or the OWNER-DECISION hand-off (only qnfo-fleet-dashboard writes them), so nothing waits for the approve before it works 100576, and the model''s wording ''now owner-authorized'' in that task is not an authorization. Issue 100576 is held by control_registry owner-authorization-hold-100576 and a note on the issue: it must not be executed before the approve exists in human_responses with the OWNER-DECISION hand-off.'), '(the server''s own marker), or an owner-session decline of every part with the card closed. It does not pass while the card is merely open,', '(the server''s own marker) and the card closed because all seven items are decided, or an owner-session decline of every part with the card closed. It does not pass while the card is open (a partial approval proves nothing until the last item is decided),'),
  updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE title = 'DASH-OWNER-ACTIONS-1: re-ask the owner for the seven decisions of agent_issues 100140 (owner card ha:uia-source-fidelity-100140 was closed with Done because Approve did not exist)' AND instr(description, 'The loop that works 100576 reads that row and does not treat the task text as the approval.') > 0;

-- agent_issues 100576: it is NOT an owner authorization (guarded on its own title and on the marker, so the paragraph is appended once).
UPDATE agent_issues SET description = COALESCE(description, '') || char(10) || char(10) || 'OWNER-AUTHORIZATION-HOLD-1 (2026-10-26, migrations/2026-10-26-dash-owner-actions-followup.sql): ''now owner-authorized'' in this task is NOT an owner authorization. It is the wording of the dashboard''s model (owner_prompts op-mvln7t9l2192). The owner''s decision is a human_responses row of kind approve, credential owner-session, on owner card ha:uia-source-fidelity-100140, together with the OWNER-DECISION hand-off task in owner_prompts (visitor owner-decision), and neither exists. Do not execute this task (items 2, 4 and 5 are authorship wording in the owner''s own papers) and do not close it before that approve exists. Release: the approve and its hand-off exist; the hand-off then carries exactly the approved items to the revision and errata path of qnfo-research-exec. The hold is re-evaluated every 120 minutes (control_registry owner-authorization-hold-100576, detector fm-owner-task-100576-acted-without-approve) and is not a block without release. Close this issue with the approve row and the work it names as evidence, or with the owner''s decline and a statement that nothing was applied.',
  updated_at = CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE id = 100576 AND title LIKE 'OWNER-TASK-op-mvln7t9l2192:%' AND instr(COALESCE(description, ''), 'OWNER-AUTHORIZATION-HOLD-1') = 0;

-- The re-ask contract: the approve branch passes only when the card is closed (all seven items decided). Guarded on the old text; the Rollback line holds the old probe.
UPDATE remediation_contracts SET verify_probe = replace(verify_probe, '> 0) THEN ''reask-100140-decided'' WHEN EXISTS', '> 0) AND NOT EXISTS (SELECT 1 FROM human_actions WHERE slug = ''uia-source-fidelity-100140'' AND status = ''open'') THEN ''reask-100140-decided'' WHEN EXISTS'), action = replace(action, 'together with the OWNER-DECISION hand-off task (owner_prompts.visitor = owner-decision), or', 'together with the OWNER-DECISION hand-off task (owner_prompts.visitor = owner-decision) once the card is closed because all seven items are decided, or'),
  attempts = 0, last_verdict = NULL, next_due_at = datetime('now')
WHERE class = 'issue-' || (SELECT id FROM agent_issues WHERE title = 'DASH-OWNER-ACTIONS-1: re-ask the owner for the seven decisions of agent_issues 100140 (owner card ha:uia-source-fidelity-100140 was closed with Done because Approve did not exist)' ORDER BY id DESC LIMIT 1) AND instr(verify_probe, '> 0) THEN ''reask-100140-decided'' WHEN EXISTS') > 0;

-- control_registry (DOCTRINE-1): the hold on 100576 (reason, release condition, expiry in minutes), the two controls the first file leaned on, and the corrected gate row.
INSERT OR IGNORE INTO control_registry (control, location, kind, guards_against, critical_path, disposition, disposition_state, alternate_path, alternate_tested_at, evidence, issue_id)
VALUES ('owner-authorization-hold-100576',
  'agent_issues 100576 (owner_prompts op-mvln7t9l2192, OWNER-TASK-op-mvln7t9l2192: execute the seven fixes of agent_issues 100140, ''now owner-authorized''): the OWNER-AUTHORIZATION-HOLD-1 note appended to its description by migrations/2026-10-26-dash-owner-actions-followup.sql, read by the loop that works it; measured by remediation contract fm-owner-task-100576-acted-without-approve',
  'hold',
  'the fleet executing, or closing as done, edits to the owner''s own papers (items 2, 4 and 5 of agent_issues 100140 are authorship wording) on the dashboard model''s wording ''now owner-authorized'', which is not the owner''s authorization: human_responses holds no approve for owner card ha:uia-source-fidelity-100140 and no loop reads one',
  0,
  'keep',
  'applied',
  'Release condition: a human_responses row (kind approve, credential owner-session, key ha:uia-source-fidelity-100140) together with the OWNER-DECISION hand-off task in owner_prompts (visitor owner-decision). The owner makes it with one tap per item at fleet.qnfo.org, and the hand-off, not this task, then carries the approved items to the revision and errata path of qnfo-research-exec. Every other task of the fleet proceeds: the hold covers this one task and nothing waits on it',
  NULL,
  'recorded reason: agent_issues 100576 (open, high, no doer on 2026-10-26) tells the fleet to apply the seven fixes as ''now owner-authorized'', wording the dashboard''s model produced 46 seconds before the owner pressed Done on the card, while the notes of that minute (human_responses 49 and 50) say authorization is pending and human_responses holds no approve; a search of every worker.js on main finds no reader of human_responses kind approve or of the OWNER-DECISION hand-off, so no loop separates the two. Expiry: 120 minutes. The hold is re-evaluated at least every 120 minutes (the detector fm-owner-task-100576-acted-without-approve and the re-ask contract of agent_issues 1000412 re-read the release condition every 60 minutes) and lapses the minute the approve exists; it is a hold with a release, not a block. Revert: strip the OWNER-AUTHORIZATION-HOLD-1 paragraph from the issue and remove this row (the Rollback line of the migration does both)',
  100576);

INSERT OR IGNORE INTO control_registry (control, location, kind, guards_against, critical_path, disposition, disposition_state, alternate_path, alternate_tested_at, evidence, issue_id)
VALUES ('dash-owner-decision-asks-gate',
  'qnfo-fleet-dashboard decAsksDecision and DEC_ASK_RX (the words approve, authorize, decline, pick one or choose one in the card''s action or title; a receipt card never asks): decApprove, cmdDecide, ownerDecisionView and decCardHtml offer Approve and Decline only for such a card; on / and on /classic',
  'gate',
  'Approve or Decline offered for, typed against or recorded on an owner card that asks the owner to DO something (send an e-mail, renew a domain, create a token, sign a statement, a receipt of a closed request) and not to decide: 19 of the 40 IDENTITY-BOUND cards read on 2026-10-26 asked for no decision, and a tap would resolve the card and tell the fleet to act in the owner''s name',
  0,
  'keep',
  'applied',
  'Done or Snooze on the card',
  strftime('%Y-%m-%dT%H:%M:%SZ', 'now'),
  'qnfo-fleet-dashboard/cmd-decide.test.mjs T2 (a bare approve lists only the cards that ask; the plain card is not offered), T18 (an IDENTITY-BOUND card with no decision wording gets no decision block, page, typed verb and /api/cmd/run), T19 (a card with no issue still hands the fleet a task; a pick-one card needs the option), T28 (a receipt whose title says Approve asks for no decision: a bare approve skips it and typed approve and /api/cmd/run refuse it, Done clears it). Live D1 2026-10-26: the cards the gate keeps out of the decision path are the ones whose action is to send, renew, create or sign',
  100360);

INSERT OR IGNORE INTO control_registry (control, location, kind, guards_against, critical_path, disposition, disposition_state, alternate_path, alternate_tested_at, evidence, issue_id)
VALUES ('owner-prompt-twin-link-handoff-exempt',
  'qnfo-fleet-dashboard ownerRequestIssue (opts.noTwin) and its caller in the owner task filing (noTwin: r.visitor === OWNER_HANDOFF_VISITOR): an owner_prompts row whose visitor is owner-decision is filed as its own ticket and skips the OWNER-PROMPT-TWIN-LINK-1 twin check',
  'filter',
  'OWNER-PROMPT-TWIN-LINK-1 returning an OPEN owner-request ticket whose title text after the first '': '' is equal and filing a second card''s approval hand-off under the first card''s ticket: the reply said it was filed and the fleet never got the second decision',
  0,
  'keep',
  'applied',
  'Without the exemption the hand-off opens with the approved items, the card key and the decision number (the first 152 characters differ per card), and fm-owner-approval-without-handoff counts two approval tasks that share one issue id (expected 0)',
  strftime('%Y-%m-%dT%H:%M:%SZ', 'now'),
  'A stranger cannot reach the exemption: visitor = owner-decision is written only by ownerTaskFile with opts.handoff, whose only caller is cmdDecide after ownerCredential(owner) is owner-session. qnfo-fleet-dashboard/cmd-decide.test.mjs T22 (two approvals are two tasks under the twin check; an ordinary task twin-links as before). The other twin-link behaviour is untouched',
  100360);

UPDATE control_registry SET location = replace(location, 'with an embedded list when the table cannot be read', 'FAILING CLOSED when the table cannot be read or holds no rows: every card that asks for a decision then offers Diagnose and Done only (1.70.1; the embedded list stays as an extra layer)'), evidence = replace(evidence, 'the embedded list stands in without the table', 'with the table dropped or empty every decision card is owner-only (T18h, and T29 for each of the 73 live patterns)'),
  reviewed_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
WHERE control = 'dash-owner-decision-hard-marker-gate' AND instr(location, 'with an embedded list when the table cannot be read') > 0;

-- belief_registry: the evidence of the belief behind the card reopen gains the follow-up (INSERT OR REPLACE of the one row, every other column kept; guarded so a replay adds it once).
INSERT OR REPLACE INTO belief_registry (belief_key, claim, confidence, evidence, probe_class, built_on, created_at)
SELECT belief_key, claim, confidence, evidence || ' Follow-up 2026-10-26 (migrations/2026-10-26-dash-owner-actions-followup.sql): against the reading that the fleet may already be acting on the model''s task, no worker.js on main reads human_responses kind approve or the OWNER-DECISION marker (only qnfo-fleet-dashboard writes them) and no D1 view or trigger does, so nothing executes an approval today; agent_issues 100576 still says ''now owner-authorized'' in the model''s wording (open, high, no doer) and now carries a note that it is not an authorization (control_registry owner-authorization-hold-100576, detector fm-owner-task-100576-acted-without-approve). The confidence is unchanged: the owner''s Done is still the only act on the card, and the owner''s answer on the reopened card decides the belief.', probe_class, built_on, created_at
FROM belief_registry WHERE belief_key = 'dash-owner-done-not-a-decision' AND instr(evidence, ' Follow-up 2026-10-26 (') = 0;

INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested)
SELECT 'session_01QpQv19uh1padRwZ3u1r766:dash-owner-actions-1',
  'a gate on an owner''s decision fails closed when the data that drives it cannot be read; a task worded as an authorization is not one until the owner''s approve exists; and a statement in an issue that a loop checks something must be true of the code on main',
  'DASH-OWNER-ACTIONS-1-FOLLOWUP: dashboard 1.70.1 loads receipt cards as receipts (a bare approve skips them; typed approve and /api/cmd/run refuse them) and fails the hard-marker gate closed (no readable marker list, no Approve); agent_issues 1000412 is corrected (no loop reads the approve); agent_issues 100576 gets a note, a control_registry hold with a 120 minute expiry and a detector; the re-ask probe passes only when the card is closed; the asks-a-decision gate and the twin-link hand-off exemption are registered',
  'two reviewers of the merged head 1.70.0 reproduced: a receipt card titled ''Approve the refreshed logo'' (source owner-request-issue) was offered as a second choice of a bare approve and approved through /api/cmd/run; with default_approve_markers unreadable the embedded regex let ''Fund a stronger code-loop model'', an e-mail address, ''unbacked rows are wiped'', ''enter the login code'', ''use the login link'' and a bare pay or paid through, all hard on the 73 live patterns; a search of every worker.js on main finds only qnfo-fleet-dashboard touching human_responses kind approve or OWNER-DECISION; agent_issues 100576 is open, high, no doer and says ''now owner-authorized''; the issue-1000412 probe passed on any approve row and any hand-off task while the card stayed open until all seven items are decided',
  'pending post-deploy measurement',
  'qnfo-fleet-dashboard decision cards, typed verbs and /api/cmd/run; the descriptions of agent_issues 1000412 and 100576; one remediation probe; control_registry and belief_registry text; no schema change and no paper edited',
  'revert the dashboard merge through the canonical path; the Rollback line of migrations/2026-10-26-dash-owner-actions-followup.sql removes the follow-up rows and restores the texts and the probe; decision_log stays append-only',
  'the owner''s decision gate fails closed instead of open, and a task held for want of an approve has a recorded reason, a release condition, a 120 minute expiry and a detector',
  'fm-owner-task-100576-acted-without-approve reads 0 on each hourly check in the next 120 minutes and until the owner approves; the issue-1000412 contract reads no-decision-reached-the-fleet until the card is closed; a closed receipt card never gets an Approve button',
  'the owner''s receipts stop being offered as decisions and an unreadable marker table can never turn a legal, money or signing card into an Approve button',
  'qnfo-fleet-dashboard/cmd-decide.test.mjs T18h, T28 and T29 (73 live patterns, page, typed verbs and /api/cmd/run; fail against 1.70.0); migrations/dash-owner-actions-followup.test.mjs replays both migrations on SQLite with the live column lists; live D1 SELECTs of agent_issues, remediation_contracts, control_registry, belief_registry, human_responses and default_approve_markers'
WHERE NOT EXISTS (SELECT 1 FROM decision_log WHERE action LIKE 'DASH-OWNER-ACTIONS-1-FOLLOWUP: %');
